private int
match(struct magic_set *ms, struct magic *magic, uint32_t nmagic,
    const unsigned char *s, size_t nbytes, size_t offset, int mode, int text,
    int flip, uint16_t *indir_count, uint16_t *name_count,
    int *printed_something, int *need_separator, int *returnval)
{
        uint32_t magindex = 0;
        unsigned int cont_level = 0;
        int returnvalv = 0, e; /* if a match is found it is set to 1*/
        int firstline = 1; /* a flag to print X\n  X\n- X */
        int print = (ms->flags & MAGIC_NODESC) == 0;

        if (returnval == NULL)
                returnval = &returnvalv;

        if (file_check_mem(ms, cont_level) == -1)
                return -1;

        for (magindex = 0; magindex < nmagic; magindex++) {
                int flush = 0;
                struct magic *m = &magic[magindex];

                if (m->type != FILE_NAME)
                if ((IS_STRING(m->type) &&
#define FLT (STRING_BINTEST | STRING_TEXTTEST)
                     ((text && (m->str_flags & FLT) == STRING_BINTEST) ||
                      (!text && (m->str_flags & FLT) == STRING_TEXTTEST))) ||
                    (m->flag & mode) != mode) {
flush:
                        /* Skip sub-tests */
                        while (magindex < nmagic - 1 &&
                            magic[magindex + 1].cont_level != 0)
                                magindex++;
                        continue; /* Skip to next top-level test*/
                }

                ms->offset = m->offset;
                ms->line = m->lineno;

                /* if main entry matches, print it... */
                switch (mget(ms, s, m, nbytes, offset, cont_level, mode, text,
                    flip, indir_count, name_count,
                    printed_something, need_separator, returnval)) {
                case -1:
                        return -1;
                case 0:
                        flush = m->reln != '!';
                        break;
                default:
                        if (m->type == FILE_INDIRECT)
                                *returnval = 1;

                        switch (magiccheck(ms, m)) {
                        case -1:
                                return -1;
                        case 0:
                                flush++;
                                break;
                        default:
                                flush = 0;
                                break;
                        }
                        break;
                }
                if (flush) {
                        /*
                         * main entry didn't match,
                         * flush its continuations
                         */
                        goto flush;
                }

                if ((e = handle_annotation(ms, m, firstline)) != 0) {
                        *need_separator = 1;
                        *printed_something = 1;
                        *returnval = 1;
                        return e;
                }

                /*
                 * If we are going to print something, we'll need to print
                 * a blank before we print something else.
                 */
                if (*m->desc) {
                        *need_separator = 1;
                        *printed_something = 1;
                        if (print_sep(ms, firstline) == -1)
                                return -1;
                }


                if (print && mprint(ms, m) == -1)
                        return -1;

                switch (moffset(ms, m, nbytes, &ms->c.li[cont_level].off)) {
                case -1:
                case 0:
                        goto flush;
                default:
                        break;
                }

                /* and any continuations that match */
                if (file_check_mem(ms, ++cont_level) == -1)
                        return -1;

                while (magindex + 1 < nmagic &&
                    magic[magindex + 1].cont_level != 0) {
                        m = &magic[++magindex];
                        ms->line = m->lineno; /* for messages */

                        if (cont_level < m->cont_level)
                                continue;
                        if (cont_level > m->cont_level) {
                                /*
                                 * We're at the end of the level
                                 * "cont_level" continuations.
                                 */
                                cont_level = m->cont_level;
                        }
                        ms->offset = m->offset;
                        if (m->flag & OFFADD) {
                                ms->offset +=
                                    ms->c.li[cont_level - 1].off;
                        }

#ifdef ENABLE_CONDITIONALS
                        if (m->cond == COND_ELSE ||
                            m->cond == COND_ELIF) {
                                if (ms->c.li[cont_level].last_match == 1)
                                        continue;
                        }
#endif
                        switch (mget(ms, s, m, nbytes, offset, cont_level, mode,
                            text, flip, indir_count, name_count,
                            printed_something, need_separator, returnval)) {
                        case -1:
                                return -1;
                        case 0:
                                if (m->reln != '!')
                                        continue;
                                flush = 1;
                                break;
                        default:
                                if (m->type == FILE_INDIRECT)
                                        *returnval = 1;
                                flush = 0;
                                break;
                        }

                        switch (flush ? 1 : magiccheck(ms, m)) {
                        case -1:
                                return -1;
                        case 0:
#ifdef ENABLE_CONDITIONALS
                                ms->c.li[cont_level].last_match = 0;
#endif
                                break;
                        default:
#ifdef ENABLE_CONDITIONALS
                                ms->c.li[cont_level].last_match = 1;
#endif
                                if (m->type == FILE_CLEAR)
                                        ms->c.li[cont_level].got_match = 0;
                                else if (ms->c.li[cont_level].got_match) {
                                        if (m->type == FILE_DEFAULT)
                                                break;
                                } else
                                        ms->c.li[cont_level].got_match = 1;

                                if ((e = handle_annotation(ms, m, firstline)) != 0) {
                                        *need_separator = 1;
                                        *printed_something = 1;
                                        *returnval = 1;
                                        return e;
                                }
                                /*
                                 * If we are going to print something,
                                 * make sure that we have a separator first.
                                 */
                                if (*m->desc) {
                                        if (!*printed_something) {
                                                *printed_something = 1;
                                                if (print_sep(ms, firstline)
                                                    == -1)
                                                        return -1;
                                        }
                                }
                                /*
                                 * This continuation matched.  Print
                                 * its message, with a blank before it
                                 * if the previous item printed and
                                 * this item isn't empty.
                                 */
                                /* space if previous printed */
                                if (*need_separator
                                    && ((m->flag & NOSPACE) == 0)
                                    && *m->desc) {
                                        if (print &&
                                            file_printf(ms, " ") == -1)
                                                return -1;
                                        *need_separator = 0;
                                }
                                if (print && mprint(ms, m) == -1)
                                        return -1;

                                switch (moffset(ms, m, nbytes,
                                    &ms->c.li[cont_level].off)) {
                                case -1:
                                case 0:
                                        flush = 1;
                                        break;
                                default:
                                        break;
                                }

                                if (*m->desc)
                                        *need_separator = 1;

                                /*
                                 * If we see any continuations
                                 * at a higher level,
                                 * process them.
                                 */
                                if (file_check_mem(ms, ++cont_level) == -1)
                                        return -1;
                                break;
                        }
                }
                if (*printed_something) {
                        firstline = 0;
                        if (print)
                                *returnval = 1;
                }
                if ((ms->flags & MAGIC_CONTINUE) == 0 && *printed_something) {
                        return *returnval; /* don't keep searching */
                }
                cont_level = 0;
        }

private int
magiccheck(struct magic_set *ms, struct magic *m)
{
        uint64_t l = m->value.q;
        uint64_t v;
        float fl, fv;
        double dl, dv;
        int matched;
        union VALUETYPE *p = &ms->ms_value;

        switch (m->type) {
        case FILE_BYTE:
                v = p->b;
                break;

        case FILE_SHORT:
        case FILE_BESHORT:
        case FILE_LESHORT:
                v = p->h;
                break;

        case FILE_LONG:
        case FILE_BELONG:
        case FILE_LELONG:
        case FILE_MELONG:
        case FILE_DATE:
        case FILE_BEDATE:
        case FILE_LEDATE:
        case FILE_MEDATE:
        case FILE_LDATE:
        case FILE_BELDATE:
        case FILE_LELDATE:
        case FILE_MELDATE:
                v = p->l;
                break;

        case FILE_QUAD:
        case FILE_LEQUAD:
        case FILE_BEQUAD:
        case FILE_QDATE:
        case FILE_BEQDATE:
        case FILE_LEQDATE:
        case FILE_QLDATE:
        case FILE_BEQLDATE:
        case FILE_LEQLDATE:
        case FILE_QWDATE:
        case FILE_BEQWDATE:
        case FILE_LEQWDATE:
                v = p->q;
                break;

        case FILE_FLOAT:
        case FILE_BEFLOAT:
        case FILE_LEFLOAT:
                fl = m->value.f;
                fv = p->f;
                switch (m->reln) {
                case 'x':
                        matched = 1;
                        break;

                case '!':
                        matched = fv != fl;
                        break;

                case '=':
                        matched = fv == fl;
                        break;

                case '>':
                        matched = fv > fl;
                        break;

                case '<':
                        matched = fv < fl;
                        break;

                default:
                        file_magerror(ms, "cannot happen with float: invalid relation `%c'",
                            m->reln);
                        return -1;
                }
                return matched;

        case FILE_DOUBLE:
        case FILE_BEDOUBLE:
        case FILE_LEDOUBLE:
                dl = m->value.d;
                dv = p->d;
                switch (m->reln) {
                case 'x':
                        matched = 1;
                        break;

                case '!':
                        matched = dv != dl;
                        break;

                case '=':
                        matched = dv == dl;
                        break;

                case '>':
                        matched = dv > dl;
                        break;

                case '<':
                        matched = dv < dl;
                        break;

                default:
                        file_magerror(ms, "cannot happen with double: invalid relation `%c'", m->reln);
                        return -1;
                }
                return matched;

        case FILE_DEFAULT:
        case FILE_CLEAR:
                l = 0;
                v = 0;
                break;

        case FILE_STRING:
        case FILE_PSTRING:
                l = 0;
                v = file_strncmp(m->value.s, p->s, (size_t)m->vallen, m->str_flags);
                break;

        case FILE_BESTRING16:
        case FILE_LESTRING16:
                l = 0;
                v = file_strncmp16(m->value.s, p->s, (size_t)m->vallen, m->str_flags);
                break;

        case FILE_SEARCH: { /* search ms->search.s for the string m->value.s */
                size_t slen;
                size_t idx;

                if (ms->search.s == NULL)
                        return 0;

                slen = MIN(m->vallen, sizeof(m->value.s));
                l = 0;
                v = 0;

                for (idx = 0; m->str_range == 0 || idx < m->str_range; idx++) {
                        if (slen + idx > ms->search.s_len)
                                return 0;

                        v = file_strncmp(m->value.s, ms->search.s + idx, slen,
                            m->str_flags);
                        if (v == 0) {   /* found match */
                                ms->search.offset += idx;
                                ms->search.rm_len = ms->search.s_len - idx;
                                break;
                        }
                }
                break;
        }
        case FILE_REGEX: {
                int rc;
                file_regex_t rx;
                const char *search;

                if (ms->search.s == NULL)
                        return 0;

                l = 0;
                rc = file_regcomp(&rx, m->value.s,
                    REG_EXTENDED|REG_NEWLINE|
                    ((m->str_flags & STRING_IGNORE_CASE) ? REG_ICASE : 0));
                if (rc) {
                        file_regerror(&rx, rc, ms);
                        v = (uint64_t)-1;
                } else {
                        regmatch_t pmatch;
                        size_t slen = ms->search.s_len;
                        char *copy;
                        if (slen != 0) {
                            copy = CAST(char *, malloc(slen));
                            if (copy == NULL)  {
                                file_regfree(&rx);
                                file_error(ms, errno,
                                    "can't allocate %" SIZE_T_FORMAT "u bytes",
                                    slen);
                                return -1;
                            }
                            memcpy(copy, ms->search.s, slen);
                            copy[--slen] = '\0';
                            search = copy;
                        } else {
                            search = CCAST(char *, "");
                            copy = NULL;
                        }
                        rc = file_regexec(&rx, (const char *)search,
                            1, &pmatch, 0);
                        free(copy);
                        switch (rc) {
                        case 0:
                                ms->search.s += (int)pmatch.rm_so;
                                ms->search.offset += (size_t)pmatch.rm_so;
                                ms->search.rm_len =
                                    (size_t)(pmatch.rm_eo - pmatch.rm_so);
                                v = 0;
                                break;

                        case REG_NOMATCH:
                                v = 1;
                                break;

                        default:
                                file_regerror(&rx, rc, ms);
                                v = (uint64_t)-1;
                                break;
                        }
                }
                file_regfree(&rx);

file_regexec(file_regex_t *rx, const char *str, size_t nmatch,
    regmatch_t* pmatch, int eflags)
{
        assert(rx->rc == 0);
        return regexec(&rx->rx, str, nmatch, pmatch, eflags);
}

protected void
file_regfree(file_regex_t *rx)
{
        if (rx->rc == 0)
                regfree(&rx->rx);
